processes.command_line:
"C:\Users\admin\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe" -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$taskLaunchDir = 'F:/Hackathon/worktrees/p16-tail-20261023/artifacts/p16-direct-cache2-perf-launch-v2'
if (Test-Path -LiteralPath $taskLaunchDir) { throw '预检/启动回执目录已存在，禁止覆盖' }
New-Item -ItemType Directory -Path $taskLaunchDir | Out-Null
$taskBefore = @{}
$taskStarted = [DateTimeOffset]::Now
$taskWatch = [Diagnostics.Stopwatch]::StartNew()
Get-Process | ForEach-Object { $taskBefore[$_.Id] = [double]$_.CPU }
Start-Sleep -Seconds 2
$taskAfter = @(Get-Process)
$taskElapsed = $taskWatch.Elapsed.TotalSeconds
$taskMeta = @{}
Get-CimInstance Win32_Process | ForEach-Object { $taskMeta[[int]$_.ProcessId] = $_ }
$taskRows = @($taskAfter | ForEach-Object { $taskProcess = $_; $taskEntry = $taskMeta[$taskProcess.Id]; [pscustomobject]@{ pid=$taskProcess.Id; name=$taskProcess.ProcessName; existed_before=$taskBefore.ContainsKey($taskProcess.Id); cpu_seconds_after=[double]$taskProcess.CPU; cpu_delta_seconds=if ($taskBefore.ContainsKey($taskProcess.Id)) { [double]$taskProcess.CPU-$taskBefore[$taskProcess.Id] } else { $null }; parent_pid=if ($taskEntry) { $taskEntry.ParentProcessId } else { $null }; command_line=if ($taskEntry) { $taskEntry.CommandLine } else { $null } } } | Sort-Object cpu_delta_seconds -Descending)
$taskPreflight = [ordered]@{ started=$taskStarted.ToString('o'); completed=[DateTimeOffset]::Now.ToString('o'); requested_interval_seconds=2; sampled_interval_seconds=$taskElapsed; unknown_processes_terminated=0; processes=$taskRows }
[IO.File]::WriteAllText((Join-Path $taskLaunchDir 'process-preflight.json'),($taskPreflight | ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
$taskRows | Where-Object { $_.cpu_delta_seconds -gt 0.10 -or $_.name -match 'python|git|cmake|gcc|cc1|clang' } | Select-Object pid,name,cpu_delta_seconds,parent_pid | Format-Table -AutoSize"
